            values = list(range(first, last + 1))
    else:
        first = _value(base, index)
        values = list(range(first, high + 1)) if slash else [first]
    values = values[::step]
    if index == _DOW:
        values = [v % 7 for v in values]
    return values


def _parse(expr):
    """Return (minutes, hours, dom, months, dow) for a valid expression.

    minutes, hours and months are sorted lists. dom is (days, last) and dow is
    (weekdays, last_weekdays, nth_weekdays); either is None if it allows any day.
    """
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    text = expr.strip()
    if text.startswith("@"):
        if text.lower() not in _SHORTCUTS:
            raise ValueError(f"unknown shortcut: {expr!r}")
        text = _SHORTCUTS[text.lower()]
    parts = re.split(r"[ \t]+", text)
    if len(parts) != 5:
        raise ValueError(f"expected five fields: {expr!r}")
    parsed = []
    for index, field in enumerate(parts):
        if field == "?":
            if index not in (_DOM, _DOW):
                raise ValueError(f"'?' not allowed here: {expr!r}")
            parsed.append(None)
            continue
        values, last, last_days, nth = set(), False, set(), set()
        for item in field.split(","):
            if index == _DOM and item == "L":
                last = True
                continue
            if index == _DOW:
                found = _LAST_DOW.fullmatch(item)
                if found:
                    day = int(found.group(1))
                    if day > 7:
                        raise ValueError(f"bad day of week: {item!r}")
                    last_days.add(day % 7)
                    continue
                found = _NTH_DOW.fullmatch(item)
                if found:
                    day, nth_k = int(found.group(1)), int(found.group(2))
                    if day > 7 or not 1 <= nth_k <= 5:
                        raise ValueError(f"bad day of week: {item!r}")
                    nth.add((day % 7, nth_k))
                    continue
            values.update(_item(item, index))
        if index == _DOM:
            parsed.append(None if field == "*" else (values, last))
        elif index == _DOW:
            parsed.append(None if field == "*" else (values, last_days, nth))
        else:
            parsed.append(sorted(values))
    return parsed


def _day_ok(dom, dow, year, month, day, first_weekday, days_in_month):
    """first_weekday is the cron weekday (0 = Sunday) of the 1st of the month."""
    if dom is not None:
        days, last = dom
        if not (day in days or (last and day == days_in_month)):
            return False
    if dow is not None:
        weekdays, last_days, nth = dow
        weekday = (first_weekday + day - 1) % 7
        if not (weekday in weekdays
                or (weekday in last_days and day + 7 > days_in_month)
                or (weekday, (day - 1) // 7 + 1) in nth):
            return False
    return True


def _month_info(year, month):
    weekday, days_in_month = calendar.monthrange(year, month)
    return (weekday + 1) % 7, days_in_month


def matches(expr, when):
    """True if the schedule expr runs at the minute of the datetime when."""
    minutes, hours, dom, months, dow = _parse(expr)
    if when.minute not in minutes or when.hour not in hours or when.month not in months:
        return False
    first_weekday, days_in_month = _month_info(when.year, when.month)
    return _day_ok(dom, dow, when.year, when.month, when.day, first_weekday, days_in_month)


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    minutes, hours, dom, months, dow = _parse(expr)
    try:
        start = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)
    except OverflowError:
        return None
    try:
        limit = after + _LIMIT
    except OverflowError:
        limit = datetime.datetime.max
    year, month = start.year, start.month
    while (year, month) <= (limit.year, limit.month):
        if month in months:
            first_weekday, days_in_month = _month_info(year, month)
            first_day = start.day if (year, month) == (start.year, start.month) else 1
            for day in range(first_day, days_in_month + 1):
                if not _day_ok(dom, dow, year, month, day, first_weekday, days_in_month):
                    continue
                found = None
                if (year, month, day) == (start.year, start.month, start.day):
                    for hour in hours:
                        if hour < start.hour:
                            continue
                        for minute in minutes:
                            if hour > start.hour or minute >= start.minute:
                                found = (hour, minute)
                                break
                        if found:
                            break
                else:
                    found = (hours[0], minutes[0])
                if found:
                    run = datetime.datetime(year, month, day, found[0], found[1])
                    return run if run <= limit else None
        month += 1
        if month > 12:
            year, month = year + 1, 1
    return None
